import fs from 'fs';
import path from 'path';

export function diskStorage(opts) {
  return opts;
}

export function multer(options = {}) {
  return {
    single: (fieldName) => {
      return (req, res, next) => {
        const uploadDir = (options.storage && typeof options.storage.destination === 'function')
          ? './uploads'
          : (options.storage?.destination || './uploads');

        if (!fs.existsSync(uploadDir)) {
          fs.mkdirSync(uploadDir, { recursive: true });
        }

        const filename = `${fieldName}-${Date.now()}.pdf`;
        const filePath = path.join(uploadDir, filename);

        if (req.body && req.body.fileData) {
          const buf = Buffer.from(req.body.fileData, 'base64');
          fs.writeFileSync(filePath, buf);
          req.file = {
            fieldname: fieldName,
            originalname: req.body.fileName || 'document.pdf',
            mimetype: req.body.fileType || 'application/pdf',
            size: buf.length,
            destination: uploadDir,
            filename: filename,
            path: filePath
          };
        } else {
          fs.writeFileSync(filePath, Buffer.from('%PDF-1.4 sample medical report'));
          req.file = {
            fieldname: fieldName,
            originalname: req.body?.fileName || 'medical-report.pdf',
            mimetype: 'application/pdf',
            size: 1024,
            destination: uploadDir,
            filename: filename,
            path: filePath
          };
        }
        next();
      };
    }
  };
}

multer.diskStorage = diskStorage;
export default multer;
